# Simple hypothesis: clean up both rectangles, turn all scattered 4s to 6s
# Only keep/fix 4s that are clearly part of a rectangle boundary

# First, let's define the exact bounding boxes
# 8-rectangle: rows 3-4, cols 15-21 (with hole at 3,16)
# 5-rectangle: rows 5-10, cols 6-11 (with holes at several positions)

# Let's fill in the holes within known bounding boxes
# 8-rectangle bounding box: (3, 15) to (4, 21)
# 5-rectangle bounding box: (5, 6) to (10, 11)

def fill_rect_holes(grid, rows, cols):
    """Fill holes in the bounding box"""
    result = [row[:] for row in grid]
    # For each cell in bounding box, if it's 4 and surrounded by the rect color, make it the rect color
    changed = True
    while changed:
        changed = False
        for r in range(rows[0], rows[1] + 1):
            for c in range(cols[0], cols[1] + 1):
                if result[r][c] == 4:
                    # Check all 8 neighbors
                    has_rect = False
                    for dr2 in range(-1, 2):
                        for dc2 in range(-1, 2):
                            if dr2 == 0 and dc2 == 0:
                                continue
                            nr, nc = r + dr2, c + dc2
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                if result[nr][nc] == 8:  # for 8-rectangle
                                    has_rect = True
                                    break
                        if has_rect:
                            break
                    if has_rect:
                        result[r][c] = 8
                        changed = True
    return result

# Fix 8-rectangle
grid8_fixed = fill_rect_holes(grid, (3, 4), (15, 21))

# Fix 5-rectangle
