# Now combine: fix both rectangles and turn all other 4s to 6s
grid_comb = [row[:] for row in grid]

# Turn all 4s that aren't in the rectangles to 6s
for r in range(11):
    for c in range(26):
        if grid_comb[r][c] == 4:
            # Check if this cell is within the 8-rectangle bbox
            if 3 <= r <= 4 and 15 <= c <= 21:
                # Check if it's surrounded by 8s - if so, keep it as 8-hole (but make it 8)
                has_8 = False
                for dr2 in range(-1, 2):
                    for dc2 in range(-1, 2):
                        if dr2 == 0 and dc2 == 0:
                            continue
                        nr, nc = r + dr2, c + dc2
                        if 0 <= nr <= 4 and 0 <= nc <= 21:
                            if grid_comb[nr][nc] == 8:
                                has_8 = True
                                break
                    if has_8:
                        break
                grid_comb[r][c] = 8 if has_8 else 6
            elif 5 <= r <= 10 and 6 <= c <= 11:
                # For 5-rectangle, fill holes
                has_5 = False
                for dr2 in range(-1, 2):
                    for dc2 in range(-1, 2):
                        if dr2 == 0 and dc2 == 0:
                            continue
                        nr, nc = r + dr2, c + dc2
                        if 0 <= nr <= 10 and 0 <= nc <= 11:
                            if grid_comb[nr][nc] == 5:
                                has_5 = True
                                break
                    if has_5:
                        break
                grid_comb[r][c] = 5 if has_5 else 6
            else:
                # Outside both rectangles: turn to 6
                grid_comb[r][c] = 6

print("\n\nFinal result:")
